"""Offset pagination over an in-memory sequence."""

from dataclasses import dataclass, field
from typing import Any, List, Sequence


@dataclass(frozen=True)
class Page:
    number: int
    per_page: int
    total_items: int
    items: List[Any] = field(default_factory=list)

    @property
    def total_pages(self) -> int:
        if self.total_items == 0:
            return 1
        return (self.total_items + self.per_page - 1) // self.per_page

    @property
    def has_next(self) -> bool:
        return self.number < self.total_pages

    @property
    def has_previous(self) -> bool:
        return self.number > 1


def paginate(items: Sequence[Any], number: int, per_page: int) -> Page:
    """Return page ``number`` (1-based) of ``items``."""
    if per_page < 1:
        raise ValueError("per_page must be at least 1")
    if number < 1:
        raise ValueError("page number must be at least 1")
    probe = Page(number=number, per_page=per_page, total_items=len(items))
    if number > probe.total_pages:
        raise ValueError("page number out of range")
    start = (number - 1) * per_page
    return Page(
        number=number,
        per_page=per_page,
        total_items=len(items),
        items=list(items[start : start + per_page]),
    )
